            Mass: gosdk.Float32(0.107),
            Radius: gosdk.Float32(0.532),
            Gravity: gosdk.Float32(0.378),
            Temperature: &shared.Temperature{
                Min: gosdk.Float32(130),
                Max: gosdk.Float32(308),
                Average: gosdk.Float32(210),
            },
        },
        Atmosphere: []shared.Atmosphere{
            shared.Atmosphere{
                Compound: gosdk.String("CO2"),
                Percentage: gosdk.Float32(95.3),
            },
            shared.Atmosphere{
                Compound: gosdk.String("CO2"),
                Percentage: gosdk.Float32(95.3),
            },
            shared.Atmosphere{
                Compound: gosdk.String("CO2"),
                Percentage: gosdk.Float32(95.3),
            },
        },
        DiscoveredAt: types.MustNewTimeFromString("1610-01-07T00:00:00Z"),
        Image: gosdk.String("https://cdn.scalar.com/photos/mars.jpg"),
        Satellites: []shared.Satellite{
            shared.Satellite{
                Name: "Phobos",
                Diameter: gosdk.Float32(22.2),
            },
        },
        Creator: &shared.UserInput{
            Name: gosdk.String("Marc"),
        },
        Tags: []string{
            "solar-system",
            "rocky",
            "explored",
        },
        CallbackURL: gosdk.String("https://example.com/webhook"),
    })
    if err != nil {
        log.Fatal(err)
    }
    if res.Planet != nil {
        // handle response
    }
}

