import org.scalar.java_sdk.ScalarJavaSDK;
import org.scalar.java_sdk.models.operations.*;

public class Application {

    public static void main(String[] args) throws Exception {

        ScalarJavaSDK sdk = ScalarJavaSDK.builder()
            .build();

        UploadImageResponse res = sdk.planets().uploadImage()
                .planetId(1L)
                .requestBody(UploadImageRequestBody.builder()
                    .image(Image.builder()
                        .fileName("example.file")
                        .content("0xA0c92e741F".getBytes(StandardCharsets.UTF_8))
                        .build())
                    .build())
                .call();

        if (res.imageUploadedMessage().isPresent()) {
            // handle response
        }
    }
}

